START TRANSACTION;

CREATE SCHEMA "foo";

CREATE SEQUENCE "foo"."used" START WITH 1 INCREMENT BY 5;

SELECT setval('"foo"."used"', 6);

CREATE TABLE "foo"."child" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647) NOT NULL,
  "pid" INTEGER DEFAULT 1,
  "Mixed Case" CHARACTER VARYING(20),
  "order" INTEGER,
  PRIMARY KEY ("id"),
  CHECK ("order" > 0)
);
INSERT INTO "foo"."child" ("id", "pid", "Mixed Case", "order") VALUES (1, 1, 'x', 3);
INSERT INTO "foo"."child" ("id", "pid", "Mixed Case", "order") VALUES (2, NULL, NULL, 4);
ALTER TABLE "foo"."child" ALTER COLUMN "id" RESTART WITH 3;
CREATE INDEX "fk1" ON "foo"."child" ("pid");

CREATE TABLE "foo"."parent" (
  "id" INTEGER NOT NULL,
  "name" CHARACTER VARYING(20) DEFAULT 'it''s',
  "note" CHARACTER VARYING(20) DEFAULT 'a\b',
  CONSTRAINT "parent_pk" PRIMARY KEY ("id"),
  CONSTRAINT "uq1" UNIQUE ("name"),
  CONSTRAINT "parent_unique_1" UNIQUE ("note") DEFERRABLE
);
INSERT INTO "foo"."parent" ("id", "name", "note") VALUES (1, 'a\b''c', NULL);
CREATE INDEX "parent_name" ON "foo"."parent" ("name" DESC, "id");

CREATE SCHEMA "nothing";

CREATE SEQUENCE "fresh" START WITH 100;

CREATE SEQUENCE "moved" START WITH 10;

ALTER SEQUENCE "moved" RESTART WITH 50;

CREATE TABLE "decimal_identity" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9999999999) NOT NULL
);
INSERT INTO "decimal_identity" ("id") VALUES (1);
ALTER TABLE "decimal_identity" ALTER COLUMN "id" RESTART WITH 2;

CREATE TABLE "descending_identity" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH -1 INCREMENT BY -1 MINVALUE -2147483648 MAXVALUE -1) NOT NULL,
  "x" INTEGER
);
INSERT INTO "descending_identity" ("id", "x") VALUES (-1, 1);
ALTER TABLE "descending_identity" ALTER COLUMN "id" RESTART WITH -2;

CREATE TABLE "no_rows" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807) NOT NULL,
  PRIMARY KEY ("id")
);

-- The generated column "g2" is a normal column: CAST(SI AS INTEGER) / 2
-- A CHECK is left out: CHAR_LENGTH(C) > 0
CREATE TABLE "types" (
  "i" INTEGER GENERATED ALWAYS AS IDENTITY (START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647) NOT NULL,
  "b" BOOLEAN DEFAULT TRUE,
  "si" SMALLINT DEFAULT NULL,
  "bi" BIGINT,
  "r" REAL,
  "d" DOUBLE PRECISION,
  "c" CHARACTER(5),
  "c2" CHARACTER(300),
  "c2_more" CHARACTER VARYING(600),
  "vc" CHARACTER VARYING(10),
  "lv" CHARACTER VARYING(5000),
  "de" DECIMAL(10, 2),
  "n" NUMERIC,
  "dt" DATE DEFAULT CURRENT_DATE,
  "t" TIME(0) WITHOUT TIME ZONE DEFAULT LOCALTIME(0),
  "tz" TIME(3) WITH TIME ZONE,
  "ts" TIMESTAMP(3) WITHOUT TIME ZONE DEFAULT LOCALTIMESTAMP(3),
  "tstz" TIMESTAMP(6) WITH TIME ZONE,
  "g" INTEGER GENERATED ALWAYS AS ("si" + 1) STORED,
  "g2" INTEGER,
  "cat" CHARACTER VARYING(128) DEFAULT CURRENT_CATALOG,
  "sch" CHARACTER VARYING(128) DEFAULT CURRENT_SCHEMA,
  CHECK ("si" BETWEEN 0 AND 100),
  CONSTRAINT "upper_vc" CHECK (UPPER("vc") = "vc" OR "vc" IS NULL),
  CONSTRAINT "types_check_3" CHECK ("vc" <> 'a\b' AND "d" < 1.5e+10)
);
INSERT INTO "types" ("i", "b", "si", "bi", "r", "d", "c", "c2", "c2_more", "vc", "lv", "de", "n", "dt", "t", "tz", "ts", "tstz", "g2", "cat", "sch") OVERRIDING SYSTEM VALUE VALUES (1, TRUE, 7, 9000000000, 1.5e0, 2.25e0, 'ab   ', 'cd                                                                                                                                                                                                                                                                                                          ', NULL, 'XY', 'long', 12.50, 3, DATE '2022-06-30', TIME '12:34:56', TIME WITH TIME ZONE '12:34:56.123+05:00', TIMESTAMP '2022-06-30 12:34:56.123', TIMESTAMP WITH TIME ZONE '2022-06-30 12:34:56.123456+05:00', 3, 'db', 'PUBLIC');
INSERT INTO "types" ("i", "b", "si", "bi", "r", "d", "c", "c2", "c2_more", "vc", "lv", "de", "n", "dt", "t", "tz", "ts", "tstz", "g2", "cat", "sch") OVERRIDING SYSTEM VALUE VALUES (2, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, DATE '2000-01-01', TIME '00:00:00', NULL, TIMESTAMP '2000-01-01 00:00:00.000', NULL, NULL, 'db', 'PUBLIC');
ALTER TABLE "types" ALTER COLUMN "i" RESTART WITH 3;
CREATE INDEX "types_c2" ON "types" ("c2", "c2_more");
CREATE INDEX "types_lv" ON "types" ("lv", "vc");
CREATE UNIQUE INDEX "types_vc" ON "types" ("vc");

CREATE TABLE "unique_identity" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647) NOT NULL,
  "x" INTEGER,
  UNIQUE ("id")
);
INSERT INTO "unique_identity" ("id", "x") VALUES (1, 1);
ALTER TABLE "unique_identity" ALTER COLUMN "id" RESTART WITH 2;

ALTER TABLE "foo"."child" ADD CONSTRAINT "fk1" FOREIGN KEY ("pid") REFERENCES "foo"."parent" ("id") ON DELETE CASCADE;
ALTER TABLE "foo"."child" ADD CONSTRAINT "fk2" FOREIGN KEY ("pid") REFERENCES "foo"."parent" ("id") ON UPDATE SET DEFAULT ON DELETE SET DEFAULT DEFERRABLE;

COMMIT;
